G=load()
I=np.array(G['Demo pair 1 input']); O=np.array(G['Demo pair 1 output'])
H,W=14,29
# candidate rule R: template T (nonzero bbox); markers = nonbg cells outside bbox.
def solve(I,O,keep_marker=True,paint_zeros=True):
    bg=int(np.unique(I)[np.bincount(I.flatten()).argmax()])
    rs,cus=np.where(I!=bg)
    ys,xs=rs.min(),cus.min()
    T={(r-ys,c-xs):int(I[r][c]) for r,c in zip(rs,cus)} if len(rs)>len(set(rs)) else {}
    # bbox approach:
    sub=I[ys:ys+max(rs.max()-ys+1,1), xs:xS:=max(cus.max()-xs+1,1)]
    T={}
    for r in range(sub.shape[0]):
        for c in range(sub.shape[1]):
            if sub[r][c]!=bg: T[(r,c)]=int(sub[r][c])
    marks=[(r,c,int(I[r][c])) for r in range(H) for c in range(W) if I[r][c]!=bg and (r,c) not in T]
    out=[row[:] for row in I.tolist()]
    for rm,cm,v in sorted(marks):
        cand=[]
        for (p,q),tv in T.items():
            tl=(rm-p, cm-q)
            ok=True
            for (a,b),val2 in T.items():
                y,x=tl[0]+a,tl[1]+b
                if not(0<=y<H and 0<=x<W): ok=False;break
                pred=val2 if paint_zeros else ('marker' if (y,x)==(rm,cm) else None)
                if pred is not None and O[y][x]!=pred: ok=False;break
            if ok: cand.append(((p,q),tv))
        if not cand: continue
        # pick placement whose anchor value == v
        cand=[c for c in cand if c[1]==v]
        if not cand:
            if keep_marker: cand=cand or [(next(iter(T)))]
            else: pass
        if cand:
            (p,q),_=cand[0]
            tl=(rm-p, cm-q)
            for (a,b),val2 in T.items():
                y,x=tl[0]+a,tl[1]+b
                if 0<=y<H and 0<=x<W: out[y][x]=val2
    return np.array(out)
print('demo keep:',solve(I,O,keep_marker=True).tolist()==O.tolist())
